# --- the inherited environment: refused, never scrubbed (the first act below the banner) --------------
# Here, not in the prologue: everything above the STAGES banner is the template's contract region, byte for
# byte but the header, the stage-table lines, the baked path, the shellcheck path and the SLUG line (the
# suite pins it). Nothing above reads Doppler, calls the vendor
# or runs a tracked tool, so this still refuses before any credential read (exit 64). HONEST LIMIT: the
# library resolution and the .env ignore probe above already ran under the inherited environment (neither
# reads a credential), so a variable or an exported function (git, readlink, dirname) that also misleads that
# probe runs or refuses there first (SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED, also exit 64, nothing read), and so does
# the library's --reset path, which rewrites .env and the ledger. Refused by CLASS, never by a name list:
#   - every exported GIT_* variable (a location, injected config, an exec path), except the five git never
#     consults for the reads this script runs (rev-parse, ls-files, hash-object, check-ignore): GIT_EDITOR
#     and GIT_SEQUENCE_EDITOR (harnesses set GIT_EDITOR; only commit and rebase run an editor), GIT_PAGER (no
#     read here pages), GIT_TERMINAL_PROMPT (credential prompts only) and GIT_CEILING_DIRECTORIES (it can only
#     stop discovery, and tracked_file then refuses);
#   - except the environment-injected config family (GIT_CONFIG_COUNT, GIT_CONFIG_KEY_<n>, GIT_CONFIG_VALUE_<n>,
#     GIT_CONFIG_PARAMETERS), which is UNSET here instead of refused (SOLEUR_P5_ENV_SCRUBBED): git then reads none
#     of it, which is what the refusal bought, and the repo's own full battery exports GIT_CONFIG_COUNT=1 to arm
#     its ref guard, so refusing it would make the script unrunnable under that battery (operator-agent-runnable);
#   - BASH_ENV and ENV (a file every bash or sh child sources first, the consumer wrapper included);
#   - DOPPLER_API_HOST, DOPPLER_CONFIG_DIR, the proxy variables (HTTPS_PROXY, HTTP_PROXY, ALL_PROXY, either case) and
#     SSL_CERT_FILE / SSL_CERT_DIR (each re-points or intercepts every Doppler read and write);
#   - ANY exported shell function (it replaces the command of that name here and in every bash child),
#     enumerated with `declare -Fx`, never by asking `type` about a fixed list of names.
env_refused() { # <name> <sentence>
  printf 'SOLEUR_P5_ENV_REFUSED name=%s\n' "$1"
  printf '%s Remove it from the environment and run again; nothing was changed.\n' "$2"
  exit 64
}
for v in $(compgen -e); do
  case "$v" in
    GIT_CONFIG_COUNT|GIT_CONFIG_KEY_*|GIT_CONFIG_VALUE_*|GIT_CONFIG_PARAMETERS)
      unset "$v"; printf 'SOLEUR_P5_ENV_SCRUBBED name=%s\n' "$v" ;;
  esac
done
for v in $(compgen -e); do
  case "$v" in
    GIT_EDITOR|GIT_SEQUENCE_EDITOR|GIT_PAGER|GIT_TERMINAL_PROMPT|GIT_CEILING_DIRECTORIES) ;;
    GIT_*|BASH_ENV|ENV|DOPPLER_API_HOST)
      env_refused "$v" "This script will not run with ${v} set: it would redirect what git, Doppler or a bash child reads, runs or writes." ;;
    DOPPLER_CONFIG_DIR|HTTPS_PROXY|https_proxy|HTTP_PROXY|http_proxy|ALL_PROXY|all_proxy|SSL_CERT_FILE|SSL_CERT_DIR)
      env_refused "$v" "This script will not run with ${v} set: it would re-point or intercept every Doppler read and write." ;;
  esac
done
while read -r _ _ v; do
  env_refused "function:${v}" "This script will not run while ${v} is an exported shell function: it would replace the command of that name."
done < <(declare -Fx)
unset v

# --- the MANIFEST (everything a rotation changes in this file, CTO F18) ---------------------------------
# One line per key: the key, the 8-character prefix of the OLD token's id (a non-secret id the
# vendor's verify endpoint answers, so an edit cannot make an old value read as new), and every
# holder (project/config) the key is written to. soleur/prd_terraform is always first. AUDIT's
# holders are only the configs with a named consumer (CTO F20); its dev_personal and dev_scheduled
# copies are deleted by an operator hold before `verify`. The parser reads these lines wherever they sit.
#   key                                      | pinned old id | holders (project/config)
# P5-MANIFEST CF_API_TOKEN_AUDIT             | dd6d1427      | soleur/prd_terraform soleur/dev
# P5-MANIFEST CF_API_TOKEN_ANALYTICS_READ    | 5993721f      | soleur/prd_terraform
# P5-MANIFEST CF_API_TOKEN_PAGERULES_READ    | 86aa993e      | soleur/prd_terraform
# The census floor (CTO D2): the Doppler projects the operator identity listed on 2026-11-27. A listing
# without any of them is census-blind; the soleur configs come from the tracked inventory file.
# P5-PROJECT-FLOOR soleur soleur-infra-privileged soleur-inngest soleur-registry soleur-deploy-channel soleur-infra-app soleur-github-app soleur-git-data-root example-project

#
# Four stages (plan "Phase 3 - the bootstrap"):
#   inventory      read   per key: the REFERENCE (which prd_terraform copy holds the pinned old token)
#                         and the narrow census (every config of every project Doppler lists, the key's
#                         own name only), printed as old / new / other / absent per holder;
#   swap           write  per key with a staged <KEY>_NEXT: <KEY> -> <KEY>_PREV (only while <KEY> verifies
#                         the pinned id), a fresh check that <KEY>_PREV verifies the pinned id, then
#                         <KEY>_NEXT -> <KEY>, then the _NEXT delete only after an equal digest;
#   holder-copies  write  every manifest holder other than prd_terraform whose digest equals <KEY>_PREV's
#                         gets <KEY>; a holder with a third value, no key, or no read refuses the stage
#                         before any write;
#   verify         read   per key: <KEY> active and not the pinned id, the consumer read, the census
#                         (exactly one old copy, at prd_terraform <KEY>_PREV); on ok with source=PREV it
#                         prints SOLEUR_P5_REVOKE_READY (CTO F13); after the revoke (no reference, _PREV
#                         denied) a key that passes the rest is verdict=revoked (CTO D6). Inventory and
#                         verify print each key's SOLEUR_P5_PREV state. The standalone drift run is the
#                         runbook's, not a verify gate (CTO D3).
# No stage calls the dashboard, deletes a token, writes outside the manifest holders, or writes
# soleur-infra-privileged (a manifest holder outside project soleur is refused at parse time).
#
# CONTRACT (what the guards pin; tests/scripts/test-cf-old-login-token-remint-bootstrap.sh):
#   - a value is read byte-exact: plain_get drops exactly the CLI's one trailing newline;
#   - a token value can never add a curl config line: bearer_config builds the header and url lines
#     from ONE Doppler read in one awk pass that emits nothing for an empty value, a byte outside the
#     class, or a second line; token_chars_ok runs the same pass first so a malformed value starts no
#     curl process; swap checks every staged _NEXT that way before its first request;
#   - a token's identity is its verify answer: /accounts/<new>/tokens/verify first (account-owned
#     tokens are unknown to the user endpoint), /user/tokens/verify second. Only a JSON 400/401/403/404
#     with success:false is a denial; 429, 5xx, a non-JSON body and a transport failure are
#     SOLEUR_P5_TOKEN_UNREACHABLE (retry), never a verdict;
#   - the reference is chosen by the pinned id the vendor answers, never by a key name;
#   - the census lists names first and reads only a listed name: a failed list, or a failed get of a
#     listed name, is SOLEUR_P5_UNREADABLE, never absent; it quantifies over the LIVE project and
#     config listing, with a committed floor (CTO D2: every `# P5-PROJECT-FLOOR` project, every soleur
#     config of the tracked inventory file, every manifest config) that a narrowed listing fails;
#   - REVOKE_READY needs, per key: <KEY> active and not the pin, no _NEXT, _PREV verifying the pin with
#     status active, the key's own consumer read, the floor, no unreadable read, exactly one old copy
#     (at prd_terraform <KEY>_PREV) and every other manifest holder reading value=new;
#   - a tool run or a file read under credentials is byte-identical to its committed HEAD blob
#     (tracked_file, filters off); an exported GIT_* variable (bar five inert ones; the injected-config family is unset), BASH_ENV, ENV,
#     DOPPLER_API_HOST or any exported function refuses the run; the wrapper gets only the names it
#     reads (`doppler run --no-fallback --only-secrets ...`);
#   - the old token's state is its verify answer at prd_terraform <KEY>_PREV (SOLEUR_P5_PREV, CTO D6): after
#     the revoke (no reference, _PREV denied) verify prints verdict=revoked, never ok or REVOKE_READY; swap
#     overwrites only an absent or denied _PREV, and resumes over a pinned one;
#   - every manifest line is parsed or refused, never skipped (SOLEUR_P5_MANIFEST_INVALID line= reason=);
#   - no value, digest, length or value prefix is ever printed: holders are classes, ids are 8
#     characters, consumer reads print their first verdict line only.
# RESIDUALS (stated, not closed here):
#   - the census reads only the key's own name: a copy of an old value under another name is unseen
#     (CTO F2' dissent: the token is dead after the revoke, and the full drift run closes the scan);
#   - REVOKE_READY is valid only in the sitting that printed it, with nothing written since; this
#     script cannot see a write made after it exits (the runbook's revoke body re-checks the ids).

readonly PROJ="soleur"
readonly TFC="prd_terraform"
readonly NEW_ZONE="951ce525552201ec6c696b24251abed7"
readonly NEW_ACCT="66d4f93f7397f196544e9fe84c3557c2"
readonly CF_API="https://api.cloudflare.com/client/v4"
readonly ACCT_VERIFY_URL="${CF_API}/accounts/${NEW_ACCT}/tokens/verify"
readonly USER_VERIFY_URL="${CF_API}/user/tokens/verify"
readonly GQL_URL="${CF_API}/graphql"
readonly READONLY_REL="plugins/soleur/scripts/cloudflare-readonly.sh"
readonly INVENTORY_REL="apps/web-platform/infra/doppler-config-inventory.txt"
readonly FLOOR_TAG='# P5-PROJECT-FLOOR '
# The manifest's tag word, spelled in two pieces so that this line is not a line the parser refuses.
readonly MANIFEST_WORD="P5-MANI""FEST"
readonly NAME_RE='^[A-Za-z0-9][A-Za-z0-9_.-]{0,79}$'
EMPTY_SHA="$(printf '' | soleur_approval_sha256)"
readonly EMPTY_SHA

# --- manifest -------------------------------------------------------------------
MKEYS=(); MPIN=(); MHOLD=()
# load_manifest — parses the MANIFEST block of THIS file into MKEYS / MPIN / MHOLD. EVERY line that
# contains the tag word must be exactly `# <tag> <KEY> | <pin8> | soleur/prd_terraform [soleur/<cfg>...]`
# (one space after the tag, three fields, prd_terraform first and exact): a near-miss spelling, a
# fourth field, a duplicate key or holder, or a key ending _PREV / _NEXT is never skipped silently but
# refused, SOLEUR_P5_MANIFEST_INVALID line=<file line> reason=<shape|suffix|duplicate-key|duplicate-holder>.
# Zero keys is SOLEUR_P5_MANIFEST_EMPTY: an empty manifest would make every stage vacuous.
load_manifest() {
  local ln line k pin holders h re seen_k=" " seen_h
  MKEYS=(); MPIN=(); MHOLD=()
  re="^# ${MANIFEST_WORD} (CF_API_TOKEN_[A-Z0-9_]+) +\\| ([0-9a-f]{8}) +\\| (${PROJ}/${TFC}( ${PROJ}/[a-z0-9_]+)*)\$"
  while IFS= read -r line; do
    ln="${line%%:*}"; line="${line#*:}"
    [[ "$line" =~ $re ]] || { printf 'SOLEUR_P5_MANIFEST_INVALID line=%s reason=shape\n' "$ln"; return 1; }
    k="${BASH_REMATCH[1]}"; pin="${BASH_REMATCH[2]}"; holders="${BASH_REMATCH[3]}"
    [[ "$k" != *_PREV && "$k" != *_NEXT ]] || { printf 'SOLEUR_P5_MANIFEST_INVALID line=%s reason=suffix\n' "$ln"; return 1; }
    [[ "$seen_k" != *" $k "* ]] || { printf 'SOLEUR_P5_MANIFEST_INVALID line=%s reason=duplicate-key\n' "$ln"; return 1; }
    seen_k="${seen_k}${k} "; seen_h=" "
    for h in $holders; do
      [[ "$seen_h" != *" $h "* ]] || { printf 'SOLEUR_P5_MANIFEST_INVALID line=%s reason=duplicate-holder\n' "$ln"; return 1; }
      seen_h="${seen_h}${h} "
    done
    MKEYS[${#MKEYS[@]}]="$k"; MPIN[${#MPIN[@]}]="$pin"; MHOLD[${#MHOLD[@]}]="$holders"
  done < <(grep -n -a -F -- "$MANIFEST_WORD" "${BASH_SOURCE[0]}")
  [[ "${#MKEYS[@]}" -gt 0 ]] || { printf 'SOLEUR_P5_MANIFEST_EMPTY\n'; return 1; }
}

# --- read helpers (never print a value) ---------------------------------------

# repo_root — this file's own repository, resolved through git (never a fixed ../ count: archive-kb
# moves the spec directory one level deeper). rc 1 when it cannot be resolved.
repo_root() { git -C "$SCRIPT_DIR" rev-parse --show-toplevel 2>/dev/null; }

# tracked_file <rel> — the absolute path of a file the root TRACKS whose working-tree bytes are exactly
# the committed HEAD blob, or rc 1. A stage runs or reads nothing under credentials that is not what the
# repository committed: an untracked file, or a tracked one with an uncommitted edit, is refused
# (`hash-object` reads the bytes, so assume-unchanged and skip-worktree cannot hide an edit, and
# `--no-filters` hashes them raw, so a clean filter or an attribute cannot launder an edit into the HEAD
# blob). It prints nothing: callers capture it, and print SOLEUR_P5_UNTRUSTED_FILE themselves.
tracked_file() {
  local root wb hb
  root="$(repo_root)" || return 1
  git -C "$root" ls-files --error-unmatch -- "$1" >/dev/null 2>&1 || return 1
  [[ -r "$root/$1" ]] || return 1
  wb="$(git -C "$root" hash-object --no-filters -- "$1" 2>/dev/null)" || return 1
  hb="$(git -C "$root" rev-parse -q --verify "HEAD:$1" 2>/dev/null)" || return 1
  [[ -n "$wb" && "$wb" == "$hb" ]] || return 1
  printf '%s/%s' "$root" "$1"
}

# names_fresh <project> <config> — sets NAMES to the secret NAMES of one config, one per line. rc 1
# unless Doppler returned a non-empty object keyed by upper-case names: an empty or reshaped answer
# is inconclusive. names_cached is the same read, cached for the rest of this invocation.
NAMES=""
NC_KEY=(); NC_VAL=()
names_fresh() {
  local raw
  NAMES=""
  raw="$(doppler secrets --only-names --json -p "$1" -c "$2" 2>/dev/null)" || return 1
  NAMES="$(jq -er 'if type == "object" and length > 0 and (keys | all(test("^[A-Z0-9_]+$"))) then keys[] else error("not a names object") end' <<<"$raw" 2>/dev/null)" || { NAMES=""; return 1; }
}
names_cached() {
  local i
  for i in ${NC_KEY[@]+"${!NC_KEY[@]}"}; do
    if [[ "${NC_KEY[i]}" == "$1/$2" ]]; then NAMES="${NC_VAL[i]}"; return 0; fi
  done
  names_fresh "$1" "$2" || return 1
  NC_KEY[${#NC_KEY[@]}]="$1/$2"; NC_VAL[${#NC_VAL[@]}]="$NAMES"
}

# in_names <name> <names-blob> — exact-line membership.
in_names() { grep -qxF -- "$1" <<<"$2"; }

# plain_get <project> <config> <name> — a secret value on stdout, byte-exact. `secrets get --plain`
# ends its output with ONE newline that is not part of the value; the awk drops exactly that final
# newline and keeps an embedded one. A failed get fails the pipe (pipefail is on script-wide). A token
# value is never captured in a variable.
plain_get() {
  doppler secrets get "$3" -p "$1" -c "$2" --plain 2>/dev/null | LC_ALL=C awk 'NR>1{printf "\n"} {printf "%s",$0}'
}

# digest_of <project> <config> <name> — sha256 of a secret value, for COMPARISON only (never
# printed). rc 1 when the read fails or the value is empty.
digest_of() {
  local d
  d="$(set -o pipefail; plain_get "$1" "$2" "$3" | soleur_approval_sha256)" || return 1
  [[ "$d" =~ ^[0-9a-f]{64}$ && "$d" != "$EMPTY_SHA" ]] || return 1
  printf '%s' "$d"
}

# holder_digest <project> <config> <name> — the census read: sets HD to the value's sha256 (an empty
# value yields the empty digest, which matches no token). rc 1 only when the get itself failed.
HD=""
holder_digest() {
  HD="$(set -o pipefail; plain_get "$1" "$2" "$3" | soleur_approval_sha256)" || { HD=""; return 1; }
  [[ "$HD" =~ ^[0-9a-f]{64}$ ]] || { HD=""; return 1; }
}

# id_of <project> <config> <name> — a NON-SECRET id value (32 lowercase hex), or rc 1. The `x`
# sentinel keeps `$(...)` from stripping more than plain_get did.
id_of() {
  local v
  v="$(plain_get "$1" "$2" "$3" && printf x)" || return 1
  v="${v%x}"
  [[ "$v" =~ ^[0-9a-f]{32}$ ]] || return 1
  printf '%s' "$v"
}

# bearer_config <project> <config> <name> <url> — the curl config of one bearer request, built from
# ONE Doppler read: `header = "Authorization: Bearer <v>"` and `url = "<url>"`. The awk pass emits
# NOTHING for an empty value, a byte outside the class, or a second line (the trailing printf makes a
# stored trailing newline a second, empty line), so curl gets no URL and sends no request. rc 0
# emitted; rc 1 the read failed; rc 2 malformed. Never widen the class to \n or `"`.
# shellcheck disable=SC2016  # awk program text, not a shell expansion
readonly BEARER_AWK='NR == 1 && /^[A-Za-z0-9._~+\/=-]+$/ { t = $0; next } { bad = 1 } END { if (bad || NR != 1) exit 3; printf "header = \"Authorization: Bearer %s\"\nurl = \"%s\"\n", t, u }'
bearer_config() {
  local -a ps=()
  if { plain_get "$1" "$2" "$3" && printf '\n'; } | LC_ALL=C awk -v u="$4" "$BEARER_AWK"; then ps=("${PIPESTATUS[@]}"); else ps=("${PIPESTATUS[@]}"); fi
  [[ "${ps[0]:-1}" -eq 0 ]] || return 1
  [[ "${ps[1]:-1}" -eq 0 ]] || return 2
}

# token_chars_ok <project> <config> <name> — the up-front verdict: the same pass with its output
# discarded. rc 0 well-formed; rc 2 malformed (prints SOLEUR_P5_TOKEN_MALFORMED; no curl process is
# started); rc 1 unreadable. NOT the injection boundary (bearer_config re-checks what it sends).
token_chars_ok() {
  local rc=0
  bearer_config "$1" "$2" "$3" "" >/dev/null || rc=$?
  [[ "$rc" -ne 2 ]] || printf 'SOLEUR_P5_TOKEN_MALFORMED name=%s/%s/%s\n' "$1" "$2" "$3"
  return "$rc"
}

# bearer_get <project> <config> <name> <url> [<config-line>...] — one request to <url> with the key's
# value as the bearer (a GET, or a POST when the extra config lines carry a `data` line); the body on
# stdout, then a last line holding the HTTP status. The bearer rides curl's stdin config, never argv. The
# producer exits before any extra line when the value is malformed, so curl then gets no URL at all.
# rc 0 answered; rc 1 unreadable; rc 2 malformed; rc 100+<curl rc> a transport failure.
bearer_get() {
  local -a ps=()
  { ( bearer_config "$1" "$2" "$3" "$4" || exit $?; [[ $# -le 4 ]] || printf '%s\n' "${@:5}" ) \
      | curl --disable --noproxy '*' -sS --max-time 30 --max-redirs 0 -w '\n%{http_code}' --config - 2>/dev/null
    ps=("${PIPESTATUS[@]}"); } || true
  [[ "${ps[0]:-1}" -eq 0 ]] || return "${ps[0]:-1}"
  [[ "${ps[1]:-1}" -eq 0 ]] || return $((100 + ps[1]))
}

# verify_at <project> <config> <name> <verify-url> — one verify read. rc 0 it answered: IDENT_ID is
# the 8-character id prefix and IDENT_STATUS the status; rc 1 a DENIAL (HTTP 400/401/403/404 with a
# JSON success:false body); rc 2 malformed; rc 3 no verdict (UNREACH_NOTE holds http=<code> or
# e=<curl rc>); rc 4 unreadable.
readonly VERIFY_OK='.success == true and (.result.id | type) == "string" and (.result.id | test("^[0-9a-f]{32}$")) and (.result.status | type) == "string" and (.result.status | test("^[a-z_]{1,32}$"))'
IDENT_ID=""; IDENT_STATUS=""; IDENT_OWNER=""; UNREACH_NOTE=""
verify_at() {
  local out rc=0 code body pair
  out="$(bearer_get "$1" "$2" "$3" "$4")" || rc=$?
  case "$rc" in
    0)
      code="${out##*$'\n'}"; body="${out%$'\n'*}"
      [[ "$code" =~ ^[0-9]{3}$ && "$out" == *$'\n'* ]] || code=unknown
      if [[ "$code" == 200 ]] && pair="$(jq -er "if ${VERIFY_OK} then \"\(.result.id[0:8]) \(.result.status)\" else error(\"no\") end" <<<"$body" 2>/dev/null)"; then
        IDENT_ID="${pair%% *}"; IDENT_STATUS="${pair#* }"; return 0
      fi
      case "$code" in
        400|401|403|404) jq -e '.success == false' >/dev/null 2>&1 <<<"$body" && return 1 ;;
      esac
      UNREACH_NOTE="http=${code}"; return 3 ;;
    1) return 4 ;;
    2) return 2 ;;
    *) UNREACH_NOTE="e=$((rc - 100))"; return 3 ;;
  esac
}

# token_ident <project> <config> <name> — the token's identity from the vendor: the account endpoint
# first, the user endpoint second. rc 0 IDENT_ID / IDENT_STATUS / IDENT_OWNER set; rc 1 both endpoints
# DENIED it (revoked, or not a token); rc 2 malformed (no request was sent); rc 3 unreachable on an
# endpoint that did not answer (SOLEUR_P5_TOKEN_UNREACHABLE printed; retry, never a verdict); rc 4
# unreadable.
token_ident() {
  local rc=0 a=0 u=0
  IDENT_ID=""; IDENT_STATUS=""; IDENT_OWNER=""; UNREACH_NOTE=""
  token_chars_ok "$1" "$2" "$3" || rc=$?
  case "$rc" in 0) ;; 2) return 2 ;; *) return 4 ;; esac
  verify_at "$1" "$2" "$3" "$ACCT_VERIFY_URL" || a=$?
  if [[ "$a" -eq 0 ]]; then IDENT_OWNER=account; return 0; fi
  [[ "$a" -eq 1 || "$a" -eq 3 ]] || return "$a"
  verify_at "$1" "$2" "$3" "$USER_VERIFY_URL" || u=$?
  if [[ "$u" -eq 0 ]]; then IDENT_OWNER=user; return 0; fi
  [[ "$u" -eq 1 || "$u" -eq 3 ]] || return "$u"
  if [[ "$a" -eq 3 || "$u" -eq 3 ]]; then
    printf 'SOLEUR_P5_TOKEN_UNREACHABLE name=%s/%s/%s %s\n' "$1" "$2" "$3" "$UNREACH_NOTE"
    return 3
  fi
  return 1
}

# require_tf_names <stage> — loads TF_NAMES (soleur/prd_terraform) or refuses the stage.
TF_NAMES=""
require_tf_names() {
  names_cached "$PROJ" "$TFC" || soleur_op_precondition_failed "$1" inventory "The names listing of Doppler ${PROJ}/${TFC} is unreadable or empty, so nothing can be proven absent or present. Run the inventory stage to see which read fails; nothing was changed."
  TF_NAMES="$NAMES"
}

# --- the _PREV state (CTO D6) ------------------------------------------------------
# prev_state <key> <pin> — what prd_terraform <KEY>_PREV holds, from token_ident. Prints
#   SOLEUR_P5_PREV key=<K> state=pinned|denied|other|malformed|unreadable|unreachable|absent [id=<8> owner=<account|user>]
# (id and owner only when the vendor answered: pinned, other). denied is rc 1 from token_ident (a JSON
# denial at BOTH endpoints: the revoked old token); unreachable (rc 3) is never a verdict. Sets PREV_KEY,
# PREV_STATE, PREV_ID, PREV_STATUS and PREV_OWNER, which reference_of reads for the same key.
PREV_KEY=""; PREV_STATE=""; PREV_ID=""; PREV_STATUS=""; PREV_OWNER=""
prev_state() {
  local k="$1" pin="$2" a=0
  PREV_KEY="$k"; PREV_STATE=absent; PREV_ID=""; PREV_STATUS=""; PREV_OWNER=""
  if in_names "${k}_PREV" "$TF_NAMES"; then
    token_ident "$PROJ" "$TFC" "${k}_PREV" || a=$?
    case "$a" in
      0) PREV_ID="$IDENT_ID"; PREV_STATUS="$IDENT_STATUS"; PREV_OWNER="$IDENT_OWNER"
         if [[ "$IDENT_ID" == "$pin" ]]; then PREV_STATE=pinned; else PREV_STATE=other; fi ;;
      1) PREV_STATE=denied ;;
      2) PREV_STATE=malformed ;;
      3) PREV_STATE=unreachable ;;
      *) PREV_STATE=unreadable ;;
    esac
  fi
  if [[ -n "$PREV_ID" ]]; then
    printf 'SOLEUR_P5_PREV key=%s state=%s id=%s owner=%s\n' "$k" "$PREV_STATE" "$PREV_ID" "$PREV_OWNER"
  else
    printf 'SOLEUR_P5_PREV key=%s state=%s\n' "$k" "$PREV_STATE"
  fi
}

# --- the reference (which prd_terraform copy holds the pinned old token) ---------
# reference_of <key> <pin> — prd_terraform <KEY>_PREV if it verifies the pinned id (prev_state, which the
# caller ran for this key), else <KEY> if it does, else none. Prints SOLEUR_P5_REFERENCE key=
# source=PREV|KEY|none (or unknown, rc 3, when an identity read got no verdict). Sets REF_SRC, REF_ID (8),
# REF_ST (the reference token's status), REF_OWNER (its owner), REF_D (the old value's digest) and NEW_D
# (the digest the census calls `new`: <KEY> once swapped, <KEY>_NEXT while staged).
REF_SRC=""; REF_ID=""; REF_ST=""; REF_OWNER=""; REF_D=""; NEW_D=""
reference_of() {
  local k="$1" pin="$2" a
  REF_SRC=none; REF_ID=""; REF_ST=""; REF_OWNER=""; REF_D=""; NEW_D=""
  if [[ "$PREV_KEY" != "$k" || "$PREV_STATE" == unreachable ]]; then printf 'SOLEUR_P5_REFERENCE key=%s source=unknown\n' "$k"; return 3; fi
  if [[ "$PREV_STATE" == pinned ]]; then REF_SRC=PREV; REF_ID="$PREV_ID"; REF_ST="$PREV_STATUS"; REF_OWNER="$PREV_OWNER"; fi
  if [[ "$REF_SRC" == none ]] && in_names "$k" "$TF_NAMES"; then
    a=0; token_ident "$PROJ" "$TFC" "$k" || a=$?
    if [[ "$a" -eq 3 ]]; then printf 'SOLEUR_P5_REFERENCE key=%s source=unknown\n' "$k"; return 3; fi
    if [[ "$a" -eq 0 && "$IDENT_ID" == "$pin" ]]; then REF_SRC=KEY; REF_ID="$IDENT_ID"; REF_ST="$IDENT_STATUS"; REF_OWNER="$IDENT_OWNER"; fi
  fi
  case "$REF_SRC" in
    PREV) REF_D="$(digest_of "$PROJ" "$TFC" "${k}_PREV" || true)"; NEW_D="$(digest_of "$PROJ" "$TFC" "$k" || true)" ;;
    KEY)  REF_D="$(digest_of "$PROJ" "$TFC" "$k" || true)"
          if in_names "${k}_NEXT" "$TF_NAMES"; then NEW_D="$(digest_of "$PROJ" "$TFC" "${k}_NEXT" || true)"; fi ;;
    *)    NEW_D="$(digest_of "$PROJ" "$TFC" "$k" || true)" ;;
  esac
  printf 'SOLEUR_P5_REFERENCE key=%s source=%s\n' "$k" "$REF_SRC"
}

# --- the census ------------------------------------------------------------------
# load_targets — the LIVE listing: every config of every project `doppler projects` returns. Sets CT
# ("project/config" lines), CT_BAD (listings that failed, printed as UNREADABLE), CT_MISSING (the
# committed floor's members the listing lacks) and CT_FLOOR_OK. Called once per invocation.
#
# THE FLOOR (CTO D2): the census quantifies over what the credential LISTS, and a narrowed credential
# lists less without failing. So the listing must contain every project of the `# P5-PROJECT-FLOOR`
# line (measured 2026-11-27), every soleur config of the tracked inventory file (read, never copied)
# and every config the manifest names. A superset passes; each member it lacks is one
# SOLEUR_P5_FLOOR_MISSING line, and verify then fails reason=census-floor.
CT=(); CT_BAD=(); CT_FLOOR_OK=0; CT_MISSING=()
ct_missing() {
  local m
  for m in ${CT_MISSING[@]+"${CT_MISSING[@]}"}; do [[ "$m" != "$1" ]] || return 0; done
  CT_MISSING[${#CT_MISSING[@]}]="$1"
}
load_targets() {
  local raw projects p cfgs c i h soleur_cfgs="" floor="" inv="" invf
  CT=(); CT_BAD=(); CT_FLOOR_OK=0; CT_MISSING=()
  if ! raw="$(doppler projects --json 2>/dev/null)" \
     || ! projects="$(jq -r --arg re "$NAME_RE" 'if type == "array" and all(.[]; type == "object" and (.name | type) == "string" and (.name | test($re))) then .[].name else error("not a project list") end' <<<"$raw" 2>/dev/null)"; then
    CT_BAD[${#CT_BAD[@]}]="-/-"
    projects=""
  fi
  for p in $projects; do
    if ! raw="$(doppler configs -p "$p" --json 2>/dev/null)" \
       || ! cfgs="$(jq -r --arg re "$NAME_RE" 'if type == "array" and all(.[]; type == "object" and (.name | type) == "string" and (.name | test($re))) then .[].name else error("not a config list") end' <<<"$raw" 2>/dev/null)"; then
      CT_BAD[${#CT_BAD[@]}]="${p}/-"
      continue
    fi
    for c in $cfgs; do CT[${#CT[@]}]="${p}/${c}"; done
    [[ "$p" == "$PROJ" ]] && soleur_cfgs="$cfgs"
  done
  # Exactly one floor line, else the floor stays empty and the shape check below reports it.
  if [[ "$(grep -ac "^${FLOOR_TAG}" "${BASH_SOURCE[0]}" || true)" -eq 1 ]] \
     && floor="$(grep -a "^${FLOOR_TAG}" "${BASH_SOURCE[0]}")"; then
    floor="${floor#"$FLOOR_TAG"}"
  fi
  [[ "$floor" =~ ^[A-Za-z0-9][A-Za-z0-9_.-]*(\ [A-Za-z0-9][A-Za-z0-9_.-]*)*$ ]] || { floor=""; ct_missing project-floor-line; }
  if invf="$(tracked_file "$INVENTORY_REL")"; then inv="$(grep -E '^[a-z0-9_]+$' "$invf" | sort -u || true)"
  else printf 'SOLEUR_P5_UNTRUSTED_FILE path=%s\n' "$INVENTORY_REL"; fi
  [[ -n "$inv" ]] || ct_missing "inventory:${INVENTORY_REL}"
  for p in $floor; do in_names "$p" "$projects" || ct_missing "$p"; done
  for c in $inv; do in_names "$c" "$soleur_cfgs" || ct_missing "${PROJ}/${c}"; done
  for i in "${!MKEYS[@]}"; do
    for h in ${MHOLD[i]}; do in_names "${h#*/}" "$soleur_cfgs" || ct_missing "$h"; done
  done
  if [[ -n "$soleur_cfgs" && "${#CT_MISSING[@]}" -eq 0 ]]; then CT_FLOOR_OK=1; fi
}

# census_key <key> — classify the key's own name in every listed config (plus
# <KEY>_PREV in soleur/prd_terraform) against REF_D (old) and NEW_D (new). Prints one
# SOLEUR_P5_HOLDER row per read, SOLEUR_P5_UNREADABLE per failed read, and SOLEUR_P5_CENSUS. Sets
# C_READ, C_OLD, C_UNREAD, C_PREV_OLD (1 when the old copy at prd_terraform <KEY>_PREV was seen),
# C_ELSEWHERE (every other old holder, "project/config/name") and C_HT / C_HV (each read
# "project/config/name" and its class: old, new, other, revoked, absent or unreadable).
C_READ=0; C_OLD=0; C_UNREAD=0; C_PREV_OLD=0; C_ELSEWHERE=(); C_HT=(); C_HV=()
census_key() {
  local k="$1" t p c n v ns
  C_READ=0; C_OLD=0; C_UNREAD=0; C_PREV_OLD=0; C_ELSEWHERE=(); C_HT=(); C_HV=()
  for t in ${CT[@]+"${CT[@]}"}; do
    p="${t%%/*}"; c="${t#*/}"
    if ! names_cached "$p" "$c"; then
      printf 'SOLEUR_P5_UNREADABLE project=%s config=%s\n' "$p" "$c"; C_HT[${#C_HT[@]}]="$t/$k"; C_HV[${#C_HV[@]}]=unreadable; C_UNREAD=$((C_UNREAD + 1)); continue
    fi
    C_READ=$((C_READ + 1))
    ns="$k"; [[ "$t" == "${PROJ}/${TFC}" ]] && ns="$k ${k}_PREV"
    for n in $ns; do
      if ! in_names "$n" "$NAMES"; then
        v=absent
      elif holder_digest "$p" "$c" "$n"; then
        if [[ -n "$REF_D" && "$HD" == "$REF_D" ]]; then v=old
        elif [[ -n "$NEW_D" && "$HD" == "$NEW_D" ]]; then v=new
        else v=other; fi
        # After the revoke (CTO D6): with no reference and a _PREV both endpoints deny, that copy is the
        # revoked old token, not an unknown third value.
        if [[ "$v" == other && "$t/$n" == "${PROJ}/${TFC}/${k}_PREV" && "$REF_SRC" == none && "$PREV_KEY" == "$k" && "$PREV_STATE" == denied ]]; then v=revoked; fi
      else printf 'SOLEUR_P5_UNREADABLE project=%s config=%s name=%s\n' "$p" "$c" "$n"; C_HT[${#C_HT[@]}]="$t/$n"; C_HV[${#C_HV[@]}]=unreadable; C_UNREAD=$((C_UNREAD + 1)); continue
      fi
      printf 'SOLEUR_P5_HOLDER project=%s config=%s key=%s value=%s\n' "$p" "$c" "$n" "$v"
      C_HT[${#C_HT[@]}]="$t/$n"; C_HV[${#C_HV[@]}]="$v"
      if [[ "$v" == old ]]; then
        C_OLD=$((C_OLD + 1))
        if [[ "$t/$n" == "${PROJ}/${TFC}/${k}_PREV" ]]; then C_PREV_OLD=1; else C_ELSEWHERE[${#C_ELSEWHERE[@]}]="$t/$n"; fi
      fi
    done
  done
  printf 'SOLEUR_P5_CENSUS key=%s configs_read=%s old_hits=%s\n' "$k" "$C_READ" "$C_OLD"
}
print_target_failures() {
  local b
  for b in ${CT_BAD[@]+"${CT_BAD[@]}"}; do printf 'SOLEUR_P5_UNREADABLE project=%s config=%s\n' "${b%%/*}" "${b#*/}"; done
  for b in ${CT_MISSING[@]+"${CT_MISSING[@]}"}; do printf 'SOLEUR_P5_FLOOR_MISSING name=%s\n' "$b"; done
  if [[ "$CT_FLOOR_OK" -ne 1 ]]; then printf 'SOLEUR_P5_CENSUS_FLOOR verdict=fail reason=floor-missing\n'; fi
}

# --- inventory (read) ---------------------------------------------------------
read_inventory() {
  local i k bad=0 rr
  load_manifest || return 1
  if ! names_cached "$PROJ" "$TFC"; then printf 'SOLEUR_P5_UNREADABLE project=%s config=%s\n' "$PROJ" "$TFC"; return 1; fi
  TF_NAMES="$NAMES"
  load_targets
  print_target_failures
  [[ "${#CT_BAD[@]}" -eq 0 && "$CT_FLOOR_OK" -eq 1 ]] || bad=1
  for i in "${!MKEYS[@]}"; do
    k="${MKEYS[i]}"
    printf 'SOLEUR_P5_STAGED key=%s next=%s prev=%s\n' "$k" \
      "$(in_names "${k}_NEXT" "$TF_NAMES" && echo present || echo absent)" "$(in_names "${k}_PREV" "$TF_NAMES" && echo present || echo absent)"
    prev_state "$k" "${MPIN[i]}"
    rr=0; reference_of "$k" "${MPIN[i]}" || rr=$?
    if [[ "$rr" -ne 0 ]]; then bad=1; continue; fi
    # A reference whose value cannot be read leaves the census unable to call anything old: that is
    # census-blind (exit non-zero), never old_hits=0.
    if [[ "$REF_SRC" != none && -z "$REF_D" ]]; then printf 'SOLEUR_P5_CENSUS_BLIND key=%s source=%s\n' "$k" "$REF_SRC"; bad=1; continue; fi
    census_key "$k"
    [[ "$C_UNREAD" -eq 0 ]] || bad=1
  done
  [[ "$bad" -eq 0 ]]
}

# --- write helpers (apply only; each verifies by a separate read) --------------

# copy_secret <src-cfg> <src-name> <dst-cfg> <dst-name> — inside project soleur. The value travels
# on stdin end to end, never in a variable; then the digests are compared. rc 1 on a failed read,
# write or comparison.
copy_secret() {
  local s d
  s="$(digest_of "$PROJ" "$1" "$2")" || { soleur_op_red "  cannot read ${1}/${2}"; return 1; }
  ( set -o pipefail
    plain_get "$PROJ" "$1" "$2" \
      | doppler secrets set "$4" -p "$PROJ" -c "$3" --silent >/dev/null 2>&1 ) || { soleur_op_red "  write to ${3}/${4} failed"; return 1; }
  d="$(digest_of "$PROJ" "$3" "$4")" || { printf 'SOLEUR_P5_COPY_MISMATCH src=%s/%s dst=%s/%s\n' "$1" "$2" "$3" "$4"; return 1; }
  [[ "$d" == "$s" ]] || { printf 'SOLEUR_P5_COPY_MISMATCH src=%s/%s dst=%s/%s\n' "$1" "$2" "$3" "$4"; return 1; }
  printf 'SOLEUR_P5_COPIED src=%s/%s dst=%s/%s verified=digest\n' "$1" "$2" "$3" "$4"
}

# --- swap (write) -----------------------------------------------------------------
SWAP_KEYS=(); SWAP_MODE=(); SWAP_PIN=()
swap_refuse() { soleur_op_precondition_failed swap inventory "$1 Nothing was changed."; }
# next_distinct <key> — the staged value is not a copy of any OTHER CF_API_TOKEN* key of prd_terraform
# (the key's own <KEY> and <KEY>_PREV excluded): a write-capable token staged by mistake under a read
# key's name refuses before any write (CTO D5). Compared by digest; only the other key's NAME is printed.
next_distinct() {
  local k="$1" dn n
  dn="$(digest_of "$PROJ" "$TFC" "${k}_NEXT")" || swap_refuse "${TFC}/${k}_NEXT is unreadable or empty."
  while IFS= read -r n; do
    case "$n" in CF_API_TOKEN*) ;; *) continue ;; esac
    [[ "$n" != "$k" && "$n" != "${k}_PREV" && "$n" != "${k}_NEXT" ]] || continue
    holder_digest "$PROJ" "$TFC" "$n" || swap_refuse "${TFC}/${n} is listed but unreadable, so nothing proves ${k}_NEXT is not a copy of it."
    if [[ "$HD" == "$dn" ]]; then
      printf 'SOLEUR_P5_NEXT_NOT_DISTINCT key=%s equals=%s\n' "$k" "$n"
      swap_refuse "${TFC}/${k}_NEXT holds the same token as ${TFC}/${n}, so it is not a token minted for ${k}. Re-mint it and re-stage it with the runbook hand-off."
    fi
  done <<<"$TF_NAMES"
}
plan_swap() {
  local i k pin b rc prev_ok n d dk dn dp mode nid nown
  SWAP_KEYS=(); SWAP_MODE=(); SWAP_PIN=()
  load_manifest || swap_refuse "The manifest block of this script parsed to no valid key, so there is nothing a swap could prove; fix the manifest block."
  require_tf_names swap
  # Every staged value is checked for shape BEFORE the first request of this stage.
  for k in "${MKEYS[@]}"; do if in_names "${k}_NEXT" "$TF_NAMES"; then rc=0; token_chars_ok "$PROJ" "$TFC" "${k}_NEXT" || rc=$?; [[ "$rc" -eq 0 ]] || swap_refuse "${TFC}/${k}_NEXT is malformed or unreadable, so it is not a token any request may carry. Re-stage it with the runbook hand-off."; fi; done
  for i in "${!MKEYS[@]}"; do
    k="${MKEYS[i]}"; pin="${MPIN[i]}"
    in_names "${k}_NEXT" "$TF_NAMES" || continue
    rc=0; token_ident "$PROJ" "$TFC" "${k}_NEXT" || rc=$?
    case "$rc" in
      0) ;;
      3) swap_refuse "The verify read of ${TFC}/${k}_NEXT got no verdict (rate limit, outage or network), so nothing is decided. Run this stage again later." ;;
      *) swap_refuse "${TFC}/${k}_NEXT does not verify as a token (rc ${rc}). Re-mint it and re-stage it with the runbook hand-off." ;;
    esac
    [[ "$IDENT_STATUS" == active ]] || swap_refuse "${TFC}/${k}_NEXT verifies with status ${IDENT_STATUS}, not active. Re-mint it."
    [[ "$IDENT_ID" != "$pin" ]] || swap_refuse "${TFC}/${k}_NEXT verifies the pinned OLD id ${pin}, so it is not a new token."
    nid="$IDENT_ID"; nown="$IDENT_OWNER"
    next_distinct "$k"
    # The _PREV a swap may overwrite (CTO D6): only an absent one, or one both endpoints deny (an earlier
    # rotation's revoked token). A _PREV that verifies the pin is an interrupted swap (prev_ok). Every other
    # state refuses: no verdict, or no read, is decided by a re-run; a malformed value, or any token that is
    # not the pin (whatever its status), is a pointer a copy over it would lose.
    prev_ok=0
    prev_state "$k" "$pin"
    case "$PREV_STATE" in
      pinned) prev_ok=1 ;;
      absent|denied) ;;
      unreachable) swap_refuse "The verify read of ${TFC}/${k}_PREV got no verdict, so nothing is decided. Run this stage again later." ;;
      unreadable) swap_refuse "${TFC}/${k}_PREV is listed but could not be read, so nothing is decided. Run this stage again." ;;
      malformed) swap_refuse "${TFC}/${k}_PREV holds a value that is not a well-formed token, so nothing proves which token a copy over it would lose. Decide it (runbook Halt), then run this stage again." ;;
      other)
        if [[ "$PREV_STATUS" == active ]]; then
          printf 'SOLEUR_P5_PREV_LIVE key=%s id=%s\n' "$k" "$PREV_ID"
          swap_refuse "${TFC}/${k}_PREV holds a live token (id ${PREV_ID}) that is not the pinned old id ${pin}, so copying ${k} over it would lose the only pointer to that token (an earlier rotation's revoke was skipped). Revoke or record it first (runbook Halt)."
        fi
        swap_refuse "${TFC}/${k}_PREV holds a token (id ${PREV_ID}, status ${PREV_STATUS}) that is not the pinned old id ${pin}, so copying ${k} over it would lose the only pointer to that token. Revoke or record it first (runbook Halt)." ;;
      *) swap_refuse "${TFC}/${k}_PREV is in no state this stage knows (${PREV_STATE}). Run the inventory stage." ;;
    esac
    if [[ "$prev_ok" -eq 1 ]]; then
      # An earlier run was interrupted after the _PREV copy: <KEY> holds either the staged value (only the
      # delete is left) or still the old one (the copy is left). Anything else is a value nothing else holds.
      # A read that fails is decided by a re-run, never reported as an unexpected value.
      for n in "$k" "${k}_NEXT" "${k}_PREV"; do
        d="$(digest_of "$PROJ" "$TFC" "$n")" || {
          printf 'SOLEUR_P5_UNREADABLE project=%s config=%s name=%s\n' "$PROJ" "$TFC" "$n"
          swap_refuse "${TFC}/${n} could not be read (or is empty), so nothing proves which value ${TFC}/${k} holds. Run this stage again."
        }
        case "$n" in *_NEXT) dn="$d" ;; *_PREV) dp="$d" ;; *) dk="$d" ;; esac
      done
      if [[ "$dk" == "$dn" ]]; then mode=delete
      elif [[ "$dk" == "$dp" ]]; then mode=swap
      else
        printf 'SOLEUR_P5_KEY_UNEXPECTED key=%s\n' "$k"
        swap_refuse "${TFC}/${k} holds neither the old token (${k}_PREV) nor the staged ${k}_NEXT, so a swap would overwrite a value no other key holds. Revoke or record it first (runbook Halt)."
      fi
    else
      in_names "$k" "$TF_NAMES" || swap_refuse "${TFC} has no ${k} and no ${k}_PREV that verifies the pinned id ${pin}, so the old token cannot be kept."
      b=0; token_ident "$PROJ" "$TFC" "$k" || b=$?
      [[ "$b" -ne 3 ]] || swap_refuse "The verify read of ${TFC}/${k} got no verdict, so nothing is decided. Run this stage again later."
      [[ "$b" -eq 0 && "$IDENT_ID" == "$pin" ]] || swap_refuse "${TFC}/${k}_PREV does not hold the old token and ${TFC}/${k} does not verify the pinned id ${pin}, so a swap would lose the only copy the revoke reads. Find the old token (runbook Halt) before any write."
      mode=prev+swap
    fi
    # The plan names the staged token's id and owner, so the approved digest binds WHICH token goes in: a
    # _NEXT re-staged between the plan and the apply is a plan drift (exit 75), never a silent swap.
    case "$mode" in
      delete) soleur_op_plan_op delete-staging-key "${TFC}/${k}_NEXT" ;;
      *)
        [[ "$mode" != prev+swap ]] || soleur_op_plan_op copy-old-token-to-revert-key "${TFC}/${k}->${k}_PREV"
        soleur_op_plan_op copy-staged-token "${TFC}/${k}_NEXT->${k} new_id=${nid} owner=${nown}"
        soleur_op_plan_op delete-staging-key "${TFC}/${k}_NEXT" ;;
    esac
    SWAP_KEYS[${#SWAP_KEYS[@]}]="$k"; SWAP_MODE[${#SWAP_MODE[@]}]="$mode"; SWAP_PIN[${#SWAP_PIN[@]}]="$pin"
  done
}
# prev_pinned_now <key> <pin> — at THIS moment <KEY>_PREV verifies the pinned old id (the check
# between the _PREV copy and the <KEY> write, Guard 2). A read with no verdict is reported as
# SOLEUR_P5_TOKEN_UNREACHABLE (by token_ident; re-run), never as "not pinned".
prev_pinned_now() {
  local a=0
  token_ident "$PROJ" "$TFC" "${1}_PREV" || a=$?
  [[ "$a" -eq 0 && "$IDENT_ID" == "$2" ]] && return 0
  [[ "$a" -eq 3 ]] || printf 'SOLEUR_P5_PREV_NOT_PINNED key=%s\n' "$1"
  return 1
}
# delete_next_if_equal <key> — delete <KEY>_NEXT ONLY after <KEY> provably holds the same value, then
# confirm the delete by a fresh names listing.
delete_next_if_equal() {
  local k="$1"
  if [[ "$(digest_of "$PROJ" "$TFC" "$k" || echo none)" != "$(digest_of "$PROJ" "$TFC" "${k}_NEXT" || echo unreadable)" ]]; then
    printf 'SOLEUR_P5_SWAP_MISMATCH key=%s kept=%s_NEXT\n' "$k" "$k"; return 1
  fi
  mark_changed "${TFC}/${k}_NEXT may have been deleted"
  doppler secrets delete "${k}_NEXT" -p "$PROJ" -c "$TFC" --yes >/dev/null 2>&1 || { soleur_op_red "  delete of ${TFC}/${k}_NEXT failed"; return 1; }
  if ! names_fresh "$PROJ" "$TFC" || in_names "${k}_NEXT" "$NAMES"; then
    printf 'SOLEUR_P5_DELETE_NOT_CONFIRMED name=%s_NEXT\n' "$k"; return 1
  fi
}
swap_one() { # <key> <mode> <pin>
  local k="$1" mode="$2" pin="$3"
  if [[ "$mode" != delete ]]; then
    if [[ "$mode" == prev+swap ]]; then
      mark_changed "${TFC}/${k}_PREV may have been written"
      copy_secret "$TFC" "$k" "$TFC" "${k}_PREV" || return 1
    fi
    prev_pinned_now "$k" "$pin" || return 1
    mark_changed "${TFC}/${k} may now hold the new token"
    copy_secret "$TFC" "${k}_NEXT" "$TFC" "$k" || return 1
  fi
  delete_next_if_equal "$k" || return 1
  printf 'SOLEUR_P5_SWAPPED key=%s staging=deleted verified=digest\n' "$k"
}
apply_swap() {
  local i
  # A failed key stops the stage at once: no later key is written after a known failure.
  for i in ${SWAP_KEYS[@]+"${!SWAP_KEYS[@]}"}; do
    swap_one "${SWAP_KEYS[i]}" "${SWAP_MODE[i]}" "${SWAP_PIN[i]}" || return 1
  done
}

# --- holder-copies (write) ----------------------------------------------------------
HC_K=(); HC_C=(); SW_DP=""
# require_swapped <key> <pin> — the swap's work, re-proved for EVERY key before any holder is classified:
# <KEY> verifies an active id that is not the pin (else need=swap: nothing is reported as already done
# before a swap). Sets SW_DP to the old value's digest when <KEY>_PREV verifies the pinned id; after the
# revoke (the old token denied, or its _PREV deleted) SW_DP stays empty, so no holder can classify as
# old and a holder that is not new refuses the stage.
require_swapped() {
  local k="$1" pin="$2" a=0 b=0
  SW_DP=""
  token_ident "$PROJ" "$TFC" "$k" || b=$?
  [[ "$b" -ne 3 ]] || soleur_op_precondition_failed holder-copies inventory "The verify read of ${TFC}/${k} got no verdict, so nothing is decided. Run this stage again later; nothing was changed."
  [[ "$b" -eq 0 && "$IDENT_STATUS" == active && "$IDENT_ID" != "$pin" ]] || soleur_op_precondition_failed holder-copies swap "${TFC}/${k} does not verify as an active new token. Run the swap stage first; nothing was changed."
  in_names "${k}_PREV" "$TF_NAMES" || return 0
  token_ident "$PROJ" "$TFC" "${k}_PREV" || a=$?
  [[ "$a" -ne 3 ]] || soleur_op_precondition_failed holder-copies inventory "A verify read of ${TFC}/${k}_PREV got no verdict, so nothing is decided. Run this stage again later; nothing was changed."
  [[ "$a" -ne 1 ]] || return 0
  [[ "$a" -eq 0 && "$IDENT_ID" == "$pin" ]] || soleur_op_precondition_failed holder-copies swap "${TFC}/${k}_PREV does not verify the pinned old id ${pin}, so nothing proves which value a holder holds. Run the swap stage first; nothing was changed."
  SW_DP="$(digest_of "$PROJ" "$TFC" "${k}_PREV")" || soleur_op_precondition_failed holder-copies inventory "${TFC}/${k}_PREV is unreadable. Nothing was changed."
}
plan_holder_copies() {
  local i k pin h c dk dp bad=0 HCLS
  HC_K=(); HC_C=()
  load_manifest || soleur_op_precondition_failed holder-copies inventory "The manifest block of this script parsed to no valid key; fix it. Nothing was changed."
  require_tf_names holder-copies
  for i in "${!MKEYS[@]}"; do
    k="${MKEYS[i]}"; pin="${MPIN[i]}"
    if in_names "${k}_NEXT" "$TF_NAMES"; then soleur_op_precondition_failed holder-copies swap "${TFC}/${k}_NEXT is still staged, so ${TFC}/${k} may still hold the old token and a copy would spread it. Run the swap stage first; nothing was changed."; fi
    # The swap's work is re-proved for every key first, so nothing is ever classified (or reported as
    # already done) before a swap: dp is the old value's digest, from a _PREV that verifies the pin.
    require_swapped "$k" "$pin"; dp="$SW_DP"
    dk="$(digest_of "$PROJ" "$TFC" "$k")" || soleur_op_precondition_failed holder-copies inventory "${TFC}/${k} is unreadable or empty. Nothing was changed."
    # The full classification pass: every holder is decided on its own digest BEFORE any write.
    for h in ${MHOLD[i]}; do
      [[ "$h" != "${PROJ}/${TFC}" ]] || continue
      c="${h#*/}"
      if ! names_cached "$PROJ" "$c"; then HCLS=unreadable
      elif ! in_names "$k" "$NAMES"; then HCLS=absent
      elif ! holder_digest "$PROJ" "$c" "$k"; then HCLS=unreadable
      elif [[ "$HD" == "$dk" ]]; then HCLS=new
      elif [[ -n "$dp" && "$HD" == "$dp" ]]; then HCLS=old
      else HCLS=other
      fi
      printf 'SOLEUR_P5_HOLDER_COPY key=%s holder=%s value=%s\n' "$k" "$h" "$HCLS"
      case "$HCLS" in
        old) soleur_op_plan_op copy-new-token "${TFC}/${k}->${c}/${k}"; HC_K[${#HC_K[@]}]="$k"; HC_C[${#HC_C[@]}]="$c" ;;
        new) ;;
        *) printf 'SOLEUR_P5_HOLDER_REFUSED key=%s holder=%s value=%s\n' "$k" "$h" "$HCLS"; bad=1 ;;
      esac
    done
  done
  [[ "$bad" -eq 0 ]] || soleur_op_precondition_failed holder-copies inventory "A manifest holder holds neither the old token (prd_terraform KEY_PREV) nor the new one, lacks the key, or cannot be read (the SOLEUR_P5_HOLDER_REFUSED lines name it), so no holder is written. Decide that holder in a reviewed change (runbook Halt); nothing was changed."
}
apply_holder_copies() {
  local i
  for i in ${HC_K[@]+"${!HC_K[@]}"}; do
    mark_changed "${HC_C[i]}/${HC_K[i]} may now hold the new token"
    copy_secret "$TFC" "${HC_K[i]}" "${HC_C[i]}" "${HC_K[i]}" || return 1
  done
}

# --- verify (read): the closure evidence, names and verdicts only ----------------
VBAD=0
vfail() { printf 'SOLEUR_P5_VERIFY key=%s verdict=fail reason=%s\n' "$1" "$2"; VBAD=1; }

# run_readonly <key> <subcommand> <gating yes|no> [args] — the REAL consumer wrapper, run the way its
# header documents (direct exec under `doppler run -p soleur -c prd_terraform`). `--no-fallback` keeps
# Doppler from writing a snapshot of the whole config to disk, and `--only-secrets` injects exactly the
# names the wrapper reads (its closed-environment allowlist): the Doppler source pair, the zone and
# account ids, and the key itself. Only its first stdout line is kept, and only when it has the
# wrapper's verdict shape; the body is discarded.
RO_TOOL=""
run_readonly() {
  local k="$1" sub="$2" gating="$3" out rc=0 first n; shift 3
  local -a only=()
  for n in DOPPLER_PROJECT DOPPLER_CONFIG CF_ZONE_ID CF_ACCOUNT_ID "$k"; do only+=(--only-secrets "$n"); done
  out="$(doppler run --no-fallback "${only[@]}" -p "$PROJ" -c "$TFC" -- "$RO_TOOL" "$sub" "$@" </dev/null 2>/dev/null)" || rc=$?
  first="${out%%$'\n'*}"
  [[ "$first" =~ ^cloudflare-readonly:\ [a-z-]+\ (ok|unverified\ -\ [A-Za-z0-9\ ._:\'\"\(\)-]{1,200})$ ]] || first="(unrecognized)"
  printf 'SOLEUR_P5_CONSUMER key=%s sub=%s gating=%s rc=%s line=%s\n' "$k" "$sub" "$gating" "$rc" "$first"
  return "$rc"
}

# graphql_gate <key> — a minimal zone-tag GraphQL read with the key's own token: it passes only when
# the answer names exactly the new zone and carries no errors. Prints only
# SOLEUR_P5_GRAPHQL key= zone_tag=match|mismatch errors=<n>; the body is discarded after jq.
readonly GQL_CT_LINE='header = "Content-Type: application/json"'
# shellcheck disable=SC2016  # $z is a GraphQL variable, never a shell expansion
GQL_DATA_LINE="$(printf 'data = "{\\"query\\":\\"query($z: String!) { viewer { zones(filter: {zoneTag: $z}) { zoneTag } } }\\",\\"variables\\":{\\"z\\":\\"%s\\"}}"' "$NEW_ZONE")"
readonly GQL_DATA_LINE
graphql_gate() {
  local k="$1" out code body verdict rc=0
  out="$(bearer_get "$PROJ" "$TFC" "$k" "$GQL_URL" "$GQL_CT_LINE" "$GQL_DATA_LINE")" || rc=$?
  code="${out##*$'\n'}"; body="${out%$'\n'*}"
  if [[ "$rc" -ne 0 || "$code" != 200 || "$out" != *$'\n'* ]]; then
    printf 'SOLEUR_P5_GRAPHQL key=%s zone_tag=unknown rc=%s\n' "$k" "$rc"; return 1
  fi
  verdict="$(jq -r --arg z "$NEW_ZONE" '([(.data.viewer.zones // [])[] | .zoneTag]) as $t | (if ($t | length) == 1 and $t[0] == $z then "match" else "mismatch" end) + " " + ((.errors // []) | length | tostring)' <<<"$body" 2>/dev/null)" || verdict="mismatch unknown"
  [[ "$verdict" =~ ^(match|mismatch)\ ([0-9]+|unknown)$ ]] || verdict="mismatch unknown"
  printf 'SOLEUR_P5_GRAPHQL key=%s zone_tag=%s errors=%s\n' "$k" "${verdict% *}" "${verdict#* }"
  [[ "$verdict" == "match 0" ]]
}

# consumer_read <key> — the key's own consumer read, which must exit 0. ANALYTICS gates on the
# zone-tag query; analytics-health runs after it as a non-gating line (Free-plan quantile limits).
consumer_read() {
  local k="$1"
  case "$k" in
    CF_API_TOKEN_PAGERULES_READ) run_readonly "$k" pagerules-ssl yes ;;
    CF_API_TOKEN_AUDIT) run_readonly "$k" change-history yes ;;
    CF_API_TOKEN_ANALYTICS_READ)
      graphql_gate "$k" || return 1
      run_readonly "$k" analytics-health no 1 || true  # never gates: a Free-plan limit is recorded, not a failure
      ;;
    *) printf 'SOLEUR_P5_CONSUMER key=%s sub=none gating=yes rc=1 line=(no consumer read is defined for this key)\n' "$k"; return 1 ;;
  esac
}

# verify_key <manifest-index> — one key's verdict. The first failing check is the reason. After the revoke
# (CTO D6: no reference, and prd_terraform <KEY>_PREV denied at both endpoints) every check but the
# reference and the census-blind proof still runs, and a key that passes them is verdict=revoked.
verify_key() {
  local i="$1" k pin rc o h hv j hbad revoked=0
  k="${MKEYS[i]}"; pin="${MPIN[i]}"
  prev_state "$k" "$pin"
  rc=0; token_ident "$PROJ" "$TFC" "$k" || rc=$?
  case "$rc" in
    0) ;;
    3) vfail "$k" unreachable; return 0 ;;
    2) vfail "$k" key-malformed; return 0 ;;
    4) vfail "$k" key-unreadable; return 0 ;;
    *) vfail "$k" key-not-verified; return 0 ;;
  esac
  local key_id="$IDENT_ID" key_owner="$IDENT_OWNER"
  printf 'SOLEUR_P5_KEY key=%s id=%s status=%s owner=%s\n' "$k" "$key_id" "$IDENT_STATUS" "$IDENT_OWNER"
  [[ "$IDENT_STATUS" == active ]] || { vfail "$k" key-not-active; return 0; }
  [[ "$key_id" != "$pin" ]] || { vfail "$k" key-is-old; return 0; }
  if in_names "${k}_NEXT" "$TF_NAMES"; then vfail "$k" next-staged; return 0; fi
  rc=0; reference_of "$k" "$pin" || rc=$?
  [[ "$rc" -eq 0 ]] || { vfail "$k" unreachable; return 0; }
  if [[ "$REF_SRC" == none && "$PREV_STATE" == denied ]]; then revoked=1; fi
  [[ "$revoked" -eq 1 || "$REF_SRC" == PREV ]] || { vfail "$k" no-reference; return 0; }
  [[ "$revoked" -eq 1 || "$REF_ST" == active ]] || { vfail "$k" prev-not-active; return 0; }
  [[ "$TARGETS_NEW" -eq 1 ]] || { vfail "$k" target-ids-not-new; return 0; }
  consumer_read "$k" || { vfail "$k" consumer-read; return 0; }
  census_key "$k"
  [[ "$CT_FLOOR_OK" -eq 1 ]] || { vfail "$k" census-floor; return 0; }
  [[ "$C_UNREAD" -eq 0 && "${#CT_BAD[@]}" -eq 0 ]] || { vfail "$k" census-unreadable; return 0; }
  if [[ "${#C_ELSEWHERE[@]}" -gt 0 ]]; then
    for o in "${C_ELSEWHERE[@]}"; do printf 'SOLEUR_P5_OLD_HOLDER key=%s holder=%s\n' "$k" "$o"; done
    vfail "$k" old-holder; return 0
  fi
  # Exactly one old copy, at prd_terraform <KEY>_PREV (old copies elsewhere were refused above); zero
  # old copies means the census cannot see the old value at all, which proves nothing.
  # After the revoke there is no old copy to see: the census-blind proof applies only before it.
  [[ "$revoked" -eq 1 ]] || [[ "$C_OLD" -eq 1 && "$C_PREV_OLD" -eq 1 ]] || { vfail "$k" census-blind; return 0; }
  # "No old copy elsewhere" is not "every holder has the new one": each manifest holder other than
  # prd_terraform must read value=new (its digest equals prd_terraform <KEY>'s), or the revoke would
  # leave that consumer with no working token.
  hbad=0
  for h in ${MHOLD[i]}; do
    [[ "$h" != "${PROJ}/${TFC}" ]] || continue
    hv=unlisted
    for j in ${C_HT[@]+"${!C_HT[@]}"}; do [[ "${C_HT[j]}" != "$h/$k" ]] || hv="${C_HV[j]}"; done
    [[ "$hv" == new ]] || { printf 'SOLEUR_P5_HOLDER_NOT_NEW key=%s holder=%s value=%s\n' "$k" "$h" "$hv"; hbad=1; }
  done
  [[ "$hbad" -eq 0 ]] || { vfail "$k" holder-not-new; return 0; }
  # The revoked state is a verdict of its own, never a failure (VBAD stays) and never a REVOKE_READY.
  if [[ "$revoked" -eq 1 ]]; then printf 'SOLEUR_P5_VERIFY key=%s verdict=revoked\n' "$k"; return 0; fi
  printf 'SOLEUR_P5_VERIFY key=%s verdict=ok\n' "$k"
  printf 'SOLEUR_P5_REVOKE_READY key=%s old_id=%s new_id=%s owner=%s old_owner=%s\n' "$k" "$REF_ID" "$key_id" "$key_owner" "$REF_OWNER"
}
TARGETS_NEW=0
read_verify() {
  local i z a
  VBAD=0
  load_manifest || { printf 'SOLEUR_P5_VERIFY verdict=fail\n'; return 1; }
  if ! names_cached "$PROJ" "$TFC"; then
    printf 'SOLEUR_P5_UNREADABLE project=%s config=%s\n' "$PROJ" "$TFC"; printf 'SOLEUR_P5_VERIFY verdict=fail\n'; return 1
  fi
  TF_NAMES="$NAMES"
  # The consumers read the zone and account from prd_terraform: an old id there is refused as a target.
  z="$(id_of "$PROJ" "$TFC" CF_ZONE_ID || true)"; a="$(id_of "$PROJ" "$TFC" CF_ACCOUNT_ID || true)"
  TARGETS_NEW=0; [[ "$z" == "$NEW_ZONE" && "$a" == "$NEW_ACCT" ]] && TARGETS_NEW=1
  if ! RO_TOOL="$(tracked_file "$READONLY_REL")"; then
    printf 'SOLEUR_P5_UNTRUSTED_FILE path=%s\n' "$READONLY_REL"; RO_TOOL="/nonexistent/${READONLY_REL}"
  fi
  load_targets
  print_target_failures
  for i in "${!MKEYS[@]}"; do verify_key "$i"; done
  if [[ "$VBAD" -eq 0 ]]; then printf 'SOLEUR_P5_VERIFY verdict=ok\n'; return 0; fi
  printf 'SOLEUR_P5_VERIFY verdict=fail\n'
  return 1
}

# --- the dispatcher: one stage per invocation --------------------------------
# Not a stage: the one place that applies the staged contract. A stage function
# never gates itself and never prints a stage marker (a marker printed inside a
# `$(...)` capture becomes the captured value).
dispatch_stage() {
  local stage="$1" class fn impact rollback flags="" n
  if ! class="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 2)"; then
    printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
    printf 'That stage is not declared by this script. The stages are:\n'
    soleur_op_list "${BASH_SOURCE[0]}"
    exit 64
  fi
  fn="${stage//-/_}"
  CURRENT_STAGE_INDEX=1; CURRENT_STAGE_NAME="$stage"; STAGE_CHANGED=""
  soleur_op_stage_begin 1 "$stage"
  case "$class" in
    read)
      "read_${fn}"
      soleur_op_stage_ok "$stage" 0
      ;;
    write)
      impact="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 3)"
      rollback="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 4)"
      [[ "$ROTATE_TOKEN" == "1" ]] && flags="rotate-token"
      soleur_op_plan_begin
      "plan_${fn}"
      n="$(soleur_op_plan_count)"
      if [[ "$APPLY" -ne 1 ]]; then
        soleur_op_plan_emit "$SCRIPT_REAL" "$stage" "$ROTATE_TOKEN"
        if [[ "$n" -eq 0 ]]; then soleur_op_stage_ok "$stage" 0; fi
      elif [[ "$n" -eq 0 ]]; then
        soleur_op_stage_ok "$stage" 0
      else
        if [[ -z "$PLAN_DIGEST" ]]; then
          printf 'SOLEUR_BOOTSTRAP_PLAN_DIGEST_REQUIRED stage=%s\n' "$stage"
          printf 'Run the stage without --apply first, then run the apply command exactly as the plan printed it.\n'
          SOLEUR_OP_REFUSED=1
          exit 64
        fi
        local computed
        computed="$(soleur_op_plan_digest "$SCRIPT_REAL" "$stage" "$flags" "$impact" "$rollback")"
        soleur_op_stage_gate "$SCRIPT_REAL" "$stage" "$computed" "$PLAN_DIGEST" "$impact" "$rollback" "${ORIG_ARGV[@]}"
        "apply_${fn}"
        soleur_op_stage_ok "$stage" 1 "$SOLEUR_OP_APPROVAL"
      fi
      ;;
    *)
      printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
      exit 64
      ;;
  esac
  soleur_op_stage_end 1 "$stage" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""; STAGE_CHANGED=""
}

main() {
  soleur_op_require_bins grep mktemp printenv sed date od id stat cut tr awk find doppler jq git curl sort
  soleur_op_ledger_init 1 "bootstrap.sh"
  dispatch_stage "$STAGE"
}

main "$@"
